using System;using System.Data;using System.Drawing;using System.Windows.Forms;using UCSPyayStudentRegistration.Helpers;using UCSPyayStudentRegistration.Queries;
namespace UCSPyayStudentRegistration.Forms { public class FrmApplicationDetails:StyledForm { int id;DataGridView details=new DataGridView{Dock=DockStyle.Top,Height=210,ReadOnly=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.DisplayedCells};DataGridView history=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};public FrmApplicationDetails(int applicationId){id=applicationId;Text="Application Details and History";Size=new Size(1200,680);var buttons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=68,Padding=new Padding(8)};B(buttons,"Start Review","Under Review",false);var docs=new Button{Text="Verify Documents",Width=140,Height=38};docs.Click+=delegate{new FrmDocumentVerification(id).ShowDialog(this);LoadData();};buttons.Controls.Add(docs);var pay=new Button{Text="Verify Payment",Width=135,Height=38};pay.Click+=delegate{new FrmPaymentManagement(id).ShowDialog(this);LoadData();};buttons.Controls.Add(pay);B(buttons,"Approve","Approved",false);B(buttons,"Request Correction","Needs Correction",true);B(buttons,"Reject","Rejected",true);Controls.Add(history);Controls.Add(details);Controls.Add(buttons);Controls.Add(UiTheme.Heading("Application Review","Student details, verification workflow and complete status history"));LoadData();}void B(Control p,string text,string status,bool reason){var b=new Button{Text=text,Width=reason?150:110,Height=38};b.Click+=delegate{string r="";if(reason)r=Microsoft.VisualBasic.Interaction.InputBox("Enter required reason:",text,"");try{new ApplicationQuery().SetStatus(id,status,r);LoadData();}catch(Exception ex){MessageBox.Show(ex.Message,"Action unavailable");}};p.Controls.Add(b);}void LoadData(){details.DataSource=new ApplicationQuery().Details(id);history.DataSource=new ApplicationQuery().History(id);} } }
